<?php session_start(); require 'config.php'; $type=$_GET['type']??'gallery'; if(!in_array($type,['gallery','video','audio'],true)) $type='gallery'; $stmt=db()->prepare("SELECT * FROM media WHERE type=? AND published=1 ORDER BY created_at DESC"); $stmt->execute([$type]); $items=$stmt->fetchAll(); ?><!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title><?=ucfirst($type)?> Library</title><link rel="stylesheet" href="assets/css/style.css"></head><body><header class="site-header"><div class="container nav"><a class="brand" href="index.php"><img src="assets/images/school-logo.png"><span>ME’RAJ INTERNATIONAL SCHOOL<br><small>MAIDUGURI</small></span></a><nav><a href="index.php">Home</a><a href="apply.php">Admissions</a><a href="media.php?type=gallery">Gallery</a><a href="media.php?type=audio">Audio</a><a href="media.php?type=video">Video</a></nav></div></header><section class="page-hero"><div class="container"><span class="eyebrow">ME’RAJ INTERNATIONAL SCHOOL</span><h1><?=ucfirst($type)?> Library</h1><p>Browse and explore our school collection.</p></div></section><main class="section"><div class="container"><?php if($type==='gallery'): ?><div class="gallery gallery-large"><?php foreach($items as $m): ?><div><img src="<?=e($m['file_path'])?>" alt="<?=e($m['title'])?>"><h3><?=e($m['title'])?></h3><p><?=e($m['description'])?></p></div><?php endforeach; ?></div><?php elseif($type==='video'): ?><div class="video-library"><?php foreach($items as $m): ?><article class="card"><video controls preload="metadata" src="<?=e($m['file_path'])?>"></video><h3><?=e($m['title'])?></h3><p><?=e($m['description'])?></p></article><?php endforeach; ?></div><?php else: ?><div class="audio-library"><?php foreach($items as $m): ?><article class="card"><h3><?=e($m['title'])?></h3><p><?=e($m['description'])?></p><audio controls src="<?=e($m['file_path'])?>"></audio></article><?php endforeach; ?></div><?php endif; if(!$items): ?><div class="empty">No published <?=e($type)?> items yet. The Admin can upload them from the dashboard.</div><?php endif; ?></div></main></body></html>